using System;
using System.Runtime.CompilerServices;
using System.Runtime.InteropServices;
using System.Runtime.Intrinsics;
using System.Runtime.Intrinsics.X86;
using System.Runtime.Intrinsics.Arm;

namespace ByteBitReverse;

public class BitReverser
{
    // Lookup table: index i maps to the bit-reversal of byte i.
    private static readonly byte[] LookupTable = CreateLookupTable();

    private static byte[] CreateLookupTable()
    {
        var table = new byte[256];
        for (int i = 0; i < 256; i++)
        {
            int b = i;
            b = ((b & 0xF0) >> 4) | ((b & 0x0F) << 4);
            b = ((b & 0xCC) >> 2) | ((b & 0x33) << 2);
            b = ((b & 0xAA) >> 1) | ((b & 0x55) << 1);
            table[i] = (byte)b;
        }
        return table;
    }

    public static void ReverseInPlace(Span<byte> data)
    {
        ref byte src = ref MemoryMarshal.GetReference(data);
        int length = data.Length;
        int i = 0;

        // --- SIMD path: nibble-lookup via PSHUFB / TBL ---
        // Reversed-nibble table: index n -> reversed bits of 4-bit value n,
        // shifted left 4 to land in the high nibble position.
        if (Avx2.IsSupported)
        {
            var nibbleReverse = Vector256.Create(
                0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F,
                0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
            ).AsByte();
            var mask = Vector256.Create((byte)0x0F);

            int lastBlockStart = length - Vector256<byte>.Count;
            for (; i <= lastBlockStart; i += Vector256<byte>.Count)
            {
                var v = Vector256.LoadUnsafe(ref src, (nuint)i);
                var lo = Avx2.Shuffle(nibbleReverse, Avx2.And(v, mask));
                var hi = Avx2.Shuffle(nibbleReverse, Avx2.ShiftRightLogical(v.AsInt16(), 4).AsByte() & mask);
                var result = Avx2.Or(Avx2.ShiftLeftLogical(lo.AsInt16(), 4).AsByte(), hi);
                result.StoreUnsafe(ref src, (nuint)i);
            }
        }
        else if (Ssse3.IsSupported)
        {
            var nibbleReverse = Vector128.Create(
                (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
            );
            var mask = Vector128.Create((byte)0x0F);

            int lastBlockStart = length - Vector128<byte>.Count;
            for (; i <= lastBlockStart; i += Vector128<byte>.Count)
            {
                var v = Vector128.LoadUnsafe(ref src, (nuint)i);
                var lo = Ssse3.Shuffle(nibbleReverse, v & mask);
                var hi = Ssse3.Shuffle(nibbleReverse, Sse2.ShiftRightLogical(v.AsInt16(), 4).AsByte() & mask);
                var result = Sse2.Or(Sse2.ShiftLeftLogical(lo.AsInt16(), 4).AsByte(), hi);
                result.StoreUnsafe(ref src, (nuint)i);
            }
        }
        else if (AdvSimd.Arm64.IsSupported)
        {
            var nibbleReverse = Vector128.Create(
                (byte)0x00, 0x08, 0x04, 0x0C, 0x02, 0x0A, 0x06, 0x0E,
                0x01, 0x09, 0x05, 0x0D, 0x03, 0x0B, 0x07, 0x0F
            );
            var mask = Vector128.Create((byte)0x0F);
            var four = Vector128.Create((byte)4);

            int lastBlockStart = length - Vector128<byte>.Count;
            for (; i <= lastBlockStart; i += Vector128<byte>.Count)
            {
                var v = Vector128.LoadUnsafe(ref src, (nuint)i);
                var lo = AdvSimd.Arm64.VectorTableLookup(nibbleReverse, v & mask);
                var hi = AdvSimd.Arm64.VectorTableLookup(nibbleReverse, AdvSimd.ShiftRightLogical(v, four) & mask);
                var result = AdvSimd.Or(AdvSimd.ShiftLeftLogical(lo, four), hi);
                result.StoreUnsafe(ref src, (nuint)i);
            }
        }

        // Scalar tail using the precomputed lookup table.
        ref byte tableRef = ref MemoryMarshal.GetArrayDataReference(LookupTable);
        for (; i < length; i++)
        {
            Unsafe.Add(ref src, i) = Unsafe.Add(ref tableRef, Unsafe.Add(ref src, i));
        }
    }
